//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS20000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {

};
/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {

};

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_BefIsuInfo.removeAll();
    dts_AftIsuInfo.removeAll();
    txb_ISU_NM.setValue("");
    txb_ISU_ABBRV.setValue("");
    txb_ISU_ENG_NM.setValue("");
    txb_ISU_ENG_ABBRV.setValue("");
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};


/**
 * 종목조회
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_BefIsuInfo);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcIsuEditPrcInquiry" + "&outputMessageId=INS_LIST_ETC_ISU_EDIT_PRC_INQUIRY" + "&param01=" + $c.stf.getObjectValue(txb_SRCH_ISUR_CD) + "&param02=" + $c.stf.getObjectValue(txb_pISU_NM);
    dts_BefIsuInfo.DataID = encodeURI(url);
    dts_BefIsuInfo.Reset();
};


/**
 * 변경처리
 */
scwin.ins_ChangeProc = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("change")) {
        return;
    }
    if (!confirm("변경하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/EtcInfoAction.do?method=processEtcIsuEditPrc" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&queryId=lds.ins.etc.update.processEtcIsuEditPrc";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_AftIsuInfo)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Save.Post();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "select") {
        if ($c.stf.getObjectValue(txb_SRCH_ISUR_CD) == "") {
            $c.win.alert("발행기관 코드를 입력하세요.");
            txb_SRCH_ISUR_CD.focus();
            return false;
        }
    } else if (pGubun == "batchChange") {
        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_BefIsuInfo.getTotalRow(); nRow++) {
            if (dts_BefIsuInfo.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 종목이 없습니다.");
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
            $c.win.alert("발행기관 코드를 입력하세요.");
            txb_ISUR_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_NM) == "") {
            $c.win.alert("기준명을 입력하세요.");
            return false;
        }
    } else if (pGubun == "change") {
        // 처리 대상이 존재 하는지..
        if (dts_AftIsuInfo.getTotalRow() < 1) {
            $c.win.alert("처리대상 종목이 존재하지 않습니다.");
            return false;
        }

        // 종목명 체크
        for (var nRow = 1; nRow <= dts_AftIsuInfo.getTotalRow(); nRow++) {
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_NM")) == "") {
                $c.win.alert("한글기준명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ABBRV")) == "") {
                $c.win.alert("한글기준약명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ENG_NM")) == "") {
                $c.win.alert("영문기준명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ENG_ABBRV")) == "") {
                $c.win.alert("영문기준약명을 입력하세요.");
                return false;
            }
        }
    }
    return true;
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 * 일괄적용
 */
scwin.fn_BatchChange = function() {
    // 일괄적용 사전체크
    if (!scwin.fn_ChkValid("batchChange")) {
        return;
    }

    // 헤더정보 복사
    $c.stf.CopyDataSetHeader(dts_BefIsuInfo, dts_AftIsuInfo);

    // row Copy
    scwin.fn_CopyRow();
};


/**
 * 데이터셋 RowCopy
 */
scwin.fn_CopyRow = function() {
    grd_AftIsuInfo.ReDraw = false;
    for (var nRow = 1; nRow <= dts_BefIsuInfo.getTotalRow(); nRow++) {
        if (dts_BefIsuInfo.getCellData(nRow, "CHK") == "T") {
            dts_AftIsuInfo.insertRow();
            var nLastRow = dts_AftIsuInfo.getTotalRow();
            dts_AftIsuInfo.setCellData(nLastRow, "STD_CD", dts_BefIsuInfo.getCellData(nRow, "STD_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_NM", $c.stf.getObjectValue(txb_ISU_NM));
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ABBRV", $c.stf.getObjectValue(txb_ISU_ENG_NM));
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ENG_NM", $c.stf.getObjectValue(txb_ISU_ABBRV));
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ENG_ABBRV", $c.stf.getObjectValue(txb_ISU_ENG_ABBRV));
            dts_AftIsuInfo.setCellData(nLastRow, "UNQ_ISU_NM", dts_BefIsuInfo.getCellData(nRow, "UNQ_ISU_NM"));
            dts_AftIsuInfo.setCellData(nLastRow, "UNQ_ISU_ENG_NM", dts_BefIsuInfo.getCellData(nRow, "UNQ_ISU_ENG_NM"));
            dts_AftIsuInfo.setCellData(nLastRow, "LIST_STAT_CD", dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "ACTIV_TP_CD", dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "KIND", dts_BefIsuInfo.getCellData(nRow, "KIND"));
            dts_AftIsuInfo.setCellData(nLastRow, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
            dts_AftIsuInfo.setCellData(nLastRow, "LIST_STAT_NM", dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_NM"));
        }
    }
    grd_AftIsuInfo.ReDraw = true;
};


/**
 * 체크가 가능한지 체크
 * 1. 채권은 상장이면 체크 불가
 * 2. 비활성은 체크 불가
 */
scwin.fn_IsAbleChk = function(nRow, bCheck) {
    if (bCheck == 0) {
        return;
    }

    // 3 주식워런트 체크(주식워런트 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "KIND") == "주식워런트") {
        $c.win.alert("주식워런트는 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
    // ETN 체크(ETN 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "KIND") == "ETN") {
        $c.win.alert("ETN은 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }


    // 1. 채권은 상장이면 체크 불가. -> 	모든 상장인경우 변경불가  F-226  2013.11.14
    //var tmpStdCd = dts_BefIsuInfo.NameString(nRow, "STD_CD").substr(0, 3);
    //if( tmpStdCd == "KR1" || tmpStdCd == "KR2" || tmpStdCd == "KR3" || tmpStdCd == "KR6" || tmpStdCd == "KRB"){
    //if( dts_BefIsuInfo.NameString(nRow, "KIND") == "채권" ){		모든 상장인경우 변경불가  F-226  2013.11.14
    if (dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD") == "Y") {
        $c.win.alert("상장여부 \"상장\"인 경우 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
    //}

    // 2. 활성여부 체크(비활성은 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") != "Y" && dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") != "1") {
        $c.win.alert("비활성 종목은 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
};






/**
 * 전체 체크
 */
scwin.fn_CheckAll = function(bCheck) {
    grd_BefIsuInfo.ReDraw = false;
    for (var nRow = 1; nRow <= dts_BefIsuInfo.getTotalRow(); nRow++) {
        if (dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD") == "Y") {

        } else if (dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") != "Y" && dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") != "1") {

        } else {
            if (dts_BefIsuInfo.getCellData(nRow, "KIND") == "주식워런트" || dts_BefIsuInfo.getCellData(nRow, "KIND") == "ETN") {

            } else {
                scwin.fn_Check(nRow, bCheck, false);
            }
        }
    }
    grd_BefIsuInfo.ReDraw = true;
};


/**
 * 전송여부가 N인 경우 체크박스 체크
 */
scwin.fn_Check = function(nRow, bCheck, bMsgShow) {
    dts_BefIsuInfo.setCellData(nRow, "CHK", bCheck ? "T" : "F");
};
scwin.grd_BefIsuInfo_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
    txb_pISU_NM.focus();
};
scwin.btn_search_onclick = function() {
    scwin.ins_Search();
};
scwin.dts_BefIsuInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_BefIsuInfo);
    $c.stf.alert_error(dts_BefIsuInfo);
};
scwin.dts_BefIsuInfo_OnLoadCompleted = function(rowcount) {
    if (dts_BefIsuInfo.errorMsg) {
        $c.win.alert(dts_BefIsuInfo.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_BefIsuInfo);
};
scwin.btn_basisunm_onclick = function() {
    if (txb_ISUR_CD.getValue() == "") return;
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관 코드 
    txb_param2.setValue(txb_ISUR_NM.getValue()); // 발행기관명  
    fn_GetPar = fn_GetParam;
    ins_isuNmpopupOpen(txb_ISU_NM, txb_ISU_ENG_NM, txb_ISU_ABBRV, txb_ISU_ENG_ABBRV); // 종목기준명 호출 */

};
scwin.img_SRCH_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_SRCH_ISUR_CD, txb_SRCH_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_btn_batch_change_onclick = function() {
    scwin.fn_BatchChange();
};
scwin.btn_prcnm_onclick = function() {
    if (dts_BefIsuInfo.getCellData(dts_BefIsuInfo.getRowPosition(), "STD_CD") == "") {
        return;
    }
    txb_param1.setValue(dts_BefIsuInfo.getCellData(dts_BefIsuInfo.getRowPosition(), "STD_CD")); // 표준코드 
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    //alert(txb_param1.value );
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};
scwin.btn_chg_onclick = function() {
    // 변경
    scwin.ins_ChangeProc();
};
scwin.grd_BefIsuInfo_OnCheckClick = function(col, colid, bCheck) {
    // 체크가 가능한지 체크
    scwin.fn_IsAbleChk(col, bCheck);
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_Search();
};
scwin.txb_SRCH_ISUR_CD_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_ISUR_CD_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_pISU_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        }
    }
};
scwin.img_SRCH_ISUR_CD2_onclick = function() {
    txb_SRCH_ISUR_CD.setValue("");
    txb_SRCH_ISUR_NM.setValue("");
};
scwin.img_ISUR_CD2_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};
scwin.grd_BefIsuInfo_OnHeadCheckClick = function(col, colid, bCheck) {
    scwin.fn_CheckAll(bCheck);
};
